    this.dialogElement.setAttribute('aria-modal', 'true');
    document.body.style.overflow = 'hidden';

    const dialog = this.dialogElement.querySelector('dialog');
    dialog.focus();
  }

  close() {
    this.dialogElement.hidden = true;
    this.dialogElement.removeAttribute('aria-modal');
    document.body.style.overflow = '';
    this.currentImageName = null;
  }

  handleConfirm() {
    console.log(`Deleted: ${this.currentImageName}`);
    this.close();
    this.showNotification(`"${this.currentImageName}" has been deleted from your library.`);
  }

  showNotification(message) {
    const notification = document.createElement('div');
    notification.setAttribute('role', 'status');
    notification.setAttribute('aria-live', 'polite');
    notification.className = 'notification notification-success';
    notification.textContent = message;

    document.body.appendChild(notification);

    setTimeout(() => {
      notification.remove();
    }, 3000);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new DeleteDialog();
});
