  color: var(--color-text-primary);
  line-height: 1.6;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-xl);
}

h1 {
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: var(--spacing-md);
}

.subtitle {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
  font-size: 1rem;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}

.image-card {
