  box-shadow: var(--shadow-lg);
  max-width: 480px;
  width: 90%;
  border: none;
  padding: 0;
  animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
  from {
    transform: translateY(20px);
    opacity: 0;
