+.modal-body {
+  padding: var(--spacing-lg);
+  color: var(--color-text-primary);
+}
+
+.modal-body p {
+  margin: 0 0 var(--spacing-md) 0;
+  font-size: 1rem;
+}
+
+.modal-body strong {
+  color: var(--color-danger);
+  font-weight: 600;
+}
+
+.modal-warning {
+  color: var(--color-text-secondary);
+  font-size: 0.95rem;
+  margin-bottom: 0;
+}
+
+.modal-footer {
+  display: flex;
+  gap: var(--spacing-md);
+  padding: var(--spacing-lg);
+  border-top: 1px solid var(--color-border);
+  justify-content: flex-end;
+}
+
+.modal-footer .btn {
+  flex: 1;
+}
+
+@media (max-width: 640px) {
+  .container {
+    padding: var(--spacing-lg);
+  }
+
+  h1 {
+    font-size: 1.875rem;
+  }
+
+  .gallery {
+    grid-template-columns: 1fr;
+  }
+
+  .modal {
+    width: 95%;
+  }
+
+  .modal-footer {
+    flex-direction: column;
+  }
+
+  .modal-footer .btn {
+    width: 100%;
+  }
+}
+
')
